# ============================================================
# HELPER FUNCTIONS
# ============================================================

def metric(label, value):

    st.html(
        textwrap.dedent(f"""
        <div class="metric">

            <div class="metric-label">
                {label}
            </div>

            <div class="metric-value">
                {value}
            </div>

        </div>
        """)
    )


def pred(model, X):

    y = np.asarray(
        model.predict(X)
    )

    if y.ndim == 2 and y.shape[1] > 1:

        return int(
            np.argmax(y[0])
        )

    return int(
        np.ravel(y)[0] >= 0.5
    )


def calculate_final_score(
    behavioral_probability: float,
    mri_probability: float,
    facial_probability: float,
) -> float:
    probabilities = (
        behavioral_probability,
        mri_probability,
        facial_probability,
    )
    if any(not np.isfinite(value) or not 0 <= value <= 1 for value in probabilities):
        raise ValueError("Model probabilities must be finite values between 0 and 1.")

    return (
        behavioral_probability * 0.15
        + mri_probability * 0.70
        + facial_probability * 0.15
    )


